import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create a plane geometry sized to atlas region aspect ratio (512×320 = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Create material with map node
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthTest: true,
    depthWrite: true,
  });

  // Load the sprite texture
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    // Atlas region: source (0,0,512,320) in a full atlas
    // Assuming full atlas is 512×512, region is top-left corner
    const uvOffset = new THREE.Vector2(0, 0.375); // y offset for 320px from 512 height
    const uvScale = new THREE.Vector2(1.0, 0.625); // scale for 320/512 height

    texture.offset.copy(uvOffset);
    texture.repeat.copy(uvScale);
    texture.flipY = false;

    material.map = texture;
    material.needsUpdate = true;
  });

  // Create the mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // Billboard toward camera (look at camera z-axis)
  mesh.lookAt(0, 0, 10);

  // Create the return group
  const group = new THREE.Group();
  group.add(mesh);

  // Iterate through config.textContent and render text labels
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const text = item.text || '';
    const fontSize = item.typography?.fontSize ?? 39;
    const color = item.color ?? '#e8ecf2';

    const textLabel = ctx.fontAtlas.createText(text, {
      fontSize: fontSize,
      color: color,
      align: 'center',
    });

    // Position text labels in a staggered pattern above the sprite
    textLabel.position.set(0, 0.65 + i * 0.35, 0.01);
    group.add(textLabel);
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) {
      material.map.dispose();
    }
  };

  group.userData.handlers = {};

  return group;
}
